        require(address(this).balance >= 0);
        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            initReverted = true;
        } else {
            initReverted = false;
        }
        bool setMinReverted;
        c.SetMinSum(val); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setMinReverted = true;
        } else {
            setMinReverted = false;
        }
        bool setLogReverted;
        c.SetLogFile(logAddr); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            setLogReverted = true;
        } else {
            setLogReverted = false;
        }
        assert(!initReverted && setMinReverted && setLogReverted);
    }

    receive() external payable {}
