// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val, address logAddr) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        bool initReverted;
        try c.Initialized() {
            initReverted = false;
        } catch {
            initReverted = true;
        }
        bool setMinReverted;
        try c.SetMinSum(val) {
            setMinReverted = false;
        } catch {
            setMinReverted = true;
        }
        bool setLogReverted;
        try c.SetLogFile(logAddr) {
            setLogReverted = false;
        } catch {
            setLogReverted = true;
        }
        assertTrue(!initReverted && setMinReverted && setLogReverted);
    }

    function testFuzz_run(uint256 val, address logAddr) public {
        vm.assume(logAddr.code.length == 0 && uint160(logAddr) > 0xffff && logAddr != address(this) && logAddr != address(c) && logAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && logAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(val, logAddr);
    }

    receive() external payable {}
}
